"""Command-line interface: argument parsing, JSON output and exit codes."""
import argparse
import contextlib
import io
import json
import sys

from .completion import complete_file
from .errors import SithError
from .navigation import GOTO, INFER, navigate


class _ArgumentParser(argparse.ArgumentParser):
    """An ArgumentParser that reports usage errors as SithError (exit 1)."""

    def error(self, message):
        raise SithError(message)


def _add_position_arguments(parser):
    parser.add_argument("file", help="Python source file")
    parser.add_argument("line", type=int, help="1-based line number")
    parser.add_argument("col", type=int, help="0-based column number")
    parser.add_argument("--project", default=None,
                        help="project root (default: the directory containing the file)")


def build_parser():
    parser = _ArgumentParser(prog="sith.py", description="Python code intelligence.")
    commands = parser.add_subparsers(dest="command", required=True, parser_class=_ArgumentParser)
    complete = commands.add_parser("complete", help="complete the code at a cursor position")
    _add_position_arguments(complete)
    complete.add_argument("--fuzzy", action="store_true", help="use fuzzy matching")
    infer = commands.add_parser(INFER, help="infer what the name at a cursor position evaluates to")
    _add_position_arguments(infer)
    goto = commands.add_parser(GOTO, help="find where the name at a cursor position is defined")
    _add_position_arguments(goto)
    return parser


def _run(args):
    if args.command == "complete":
        completions = complete_file(args.file, args.line, args.col, fuzzy=args.fuzzy,
                                    project=args.project)
        return "completions", [c.to_dict() for c in completions]
    definitions = navigate(args.command, args.file, args.line, args.col, project=args.project)
    return "definitions", [d.to_dict() for d in definitions]


def main(argv=None):
    key = "completions"
    try:
        args = build_parser().parse_args(argv)
        key = "completions" if args.command == "complete" else "definitions"
        # Introspected modules may print; keep STDOUT reserved for the JSON result.
        with contextlib.redirect_stdout(io.StringIO()):
            key, results = _run(args)
    except SithError as error:
        print(f"error: {error}", file=sys.stderr)
        return 1
    except Exception as error:  # analysis must never crash an editor integration
        print(f"warning: analysis failed: {error!r}", file=sys.stderr)
        results = []
    payload = {key: results}
    sys.stdout.write(json.dumps(payload, separators=(",", ":")) + "\n")
    return 0
"""Module contexts and import resolution (local files first, then installed)."""
import contextlib
import importlib
import io
import os
import warnings

from .parsing import parse_tolerant
from .scopes import ScopeBuilder
from .source import read_text
from .errors import SithError
from .values import LocalModule, RuntimeModule


class ModuleContext:
    """A parsed Python module together with its scope tree."""

    def __init__(self, path, name, tree, text=""):
        self.path = os.path.abspath(path) if path else None
        self.directory = os.path.dirname(self.path) if self.path else os.getcwd()
        self.name = name
        self.tree = tree
        self.text = text
        self.lines = text.split("\n")
        builder = ScopeBuilder(self)
        self.root = builder.build(tree)
        self.scope_by_node = builder.scope_by_node
        self.binding_by_target = builder.binding_by_target

    @property
    def is_package(self):
        return bool(self.path) and os.path.basename(self.path) == "__init__.py"

    def scope_of(self, node):
        return self.scope_by_node.get(id(node))

    def binding_of(self, node):
        """The binding created for a name node (or def/class/except node), if any."""
        return self.binding_by_target.get(id(node))


class Importer:
    """Resolves module names to values, preferring files in the project directory."""

    def __init__(self, project_dir, *extra_dirs):
        self.project_dir = project_dir
        self.search_dirs = [project_dir] + [d for d in extra_dirs if d and d != project_dir]
        self._contexts = {}
        self._runtime = {}

    def register(self, context):
        if context.path:
            self._contexts[context.path] = context

    def context_for_file(self, path, name):
        path = os.path.abspath(path)
        if path not in self._contexts:
            try:
                text = read_text(path)
            except SithError:
                return None
            self._contexts[path] = ModuleContext(path, name, parse_tolerant(text), text)
        return self._contexts[path]

    def import_absolute(self, dotted):
        """Resolve `import dotted` to a module value, or None."""
        if not dotted:
            return None
        path = None
        for directory in self.search_dirs:
            path = self._find_local(directory, dotted.split("."))
            if path:
                break
        if path:
            context = self.context_for_file(path, dotted)
            return LocalModule(context) if context else None
        return self._import_runtime(dotted)

    def import_relative(self, context, dotted, level):
        """Resolve `from <level dots><dotted> import ...` relative to `context`."""
        base = context.directory
        for _ in range(level - 1):
            base = os.path.dirname(base)
        parts = dotted.split(".") if dotted else []
        path = self._find_local(base, parts) if parts else _package_init(base)
        if not path:
            return None
        name = ".".join(p for p in [os.path.basename(base)] + parts if p)
        context = self.context_for_file(path, name)
        return LocalModule(context) if context else None

    def import_module(self, context, dotted, level=0):
        if level:
            return self.import_relative(context, dotted, level)
        return self.import_absolute(dotted)

    def local_submodule(self, module_value, name):
        """A submodule `name` of a local package, if such a file exists."""
        context = module_value.context
        if not context.is_package:
            return None
        path = self._find_local(context.directory, [name])
        if not path:
            return None
        sub = self.context_for_file(path, f"{context.name}.{name}")
        return LocalModule(sub) if sub else None

    def runtime_submodule(self, module_value, name):
        if not hasattr(module_value.obj, "__path__"):
            return None
        return self._import_runtime(f"{module_value.obj.__name__}.{name}")

    @staticmethod
    def _find_local(base, parts):
        directory = base
        for part in parts[:-1]:
            directory = os.path.join(directory, part)
            if not os.path.isdir(directory):
                return None
        last = os.path.join(directory, parts[-1])
        if os.path.isfile(last + ".py"):
            return last + ".py"
        return _package_init(last)

    def _import_runtime(self, dotted):
        if dotted not in self._runtime:
            module = None
            try:
                with warnings.catch_warnings(), contextlib.redirect_stdout(io.StringIO()):
                    warnings.simplefilter("ignore")
                    module = importlib.import_module(dotted)
            except BaseException:  # importing arbitrary modules may fail in any way
                module = None
            self._runtime[dotted] = RuntimeModule(module) if module is not None else None
        return self._runtime[dotted]


def _package_init(directory):
    init = os.path.join(directory, "__init__.py")
    return init if os.path.isfile(init) else None
"""Lazily-described completion candidates.

An entry stands for whatever a name refers to; its value and description are
only computed when the name survives prefix filtering.
"""
from .describe import (
    describe_class,
    describe_function,
    describe_module,
    describe_param,
    describe_value,
)

_UNSET = object()


class BindingEntry:
    """A name bound by a statement in parsed source."""

    def __init__(self, binding, inferrer):
        self.binding = binding
        self.inferrer = inferrer

    def value(self):
        return self.inferrer.infer_binding(self.binding)

    def describe(self, name):
        kind = self.binding.kind
        if kind == "param":
            return describe_param(name)
        if kind == "def":
            return describe_function(name)
        if kind == "class":
            return describe_class(name)
        if kind == "import":
            return describe_module(name)
        return describe_value(name, self.value())


class ValueEntry:
    """A name whose value is produced on demand by a factory."""

    def __init__(self, factory):
        self._factory = factory
        self._value = _UNSET

    def value(self):
        if self._value is _UNSET:
            try:
                self._value = self._factory()
            except Exception:
                self._value = None
        return self._value

    def describe(self, name):
        return describe_value(name, self.value())
"""Loading source documents and validating cursor positions."""
import os
from dataclasses import dataclass, field

from .errors import SithError


@dataclass
class Document:
    """A source file split into lines, with cursor-related helpers."""

    path: str
    text: str
    lines: list = field(default_factory=list)

    @property
    def directory(self):
        return os.path.dirname(os.path.abspath(self.path))

    def check_position(self, line, col):
        """Validate a 1-based line and 0-based column."""
        if line < 1 or line > len(self.lines):
            raise SithError(f"line {line} is out of range (file has {len(self.lines)} lines)")
        length = len(self.lines[line - 1])
        if col < 0 or col > length:
            raise SithError(f"column {col} is out of range (line {line} has {length} characters)")

    def text_before(self, line, col):
        """All source text preceding the cursor."""
        return "\n".join(self.lines[: line - 1] + [self.lines[line - 1][:col]])


def normalize_newlines(text):
    return text.replace("\r\n", "\n").replace("\r", "\n")


def read_text(path):
    """Read a file as UTF-8 text, raising SithError on any problem."""
    if not os.path.exists(path):
        raise SithError(f"file not found: {path}")
    if not os.path.isfile(path):
        raise SithError(f"not a regular file: {path}")
    try:
        with open(path, "rb") as handle:
            raw = handle.read()
    except OSError as exc:
        raise SithError(f"cannot read {path}: {exc}") from exc
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise SithError(f"file is not valid UTF-8: {path}") from exc
    if text.startswith("\ufeff"):
        text = text[1:]
    return normalize_newlines(text)


def load_document(path):
    text = read_text(path)
    return Document(path=path, text=text, lines=text.split("\n"))
"""Exception types used across sith."""


class SithError(Exception):
    """A user-facing error: reported on STDERR and turned into exit code 1."""
"""Formatting of completion `type` and `description` fields."""
from .values import CLASS, FUNCTION, INSTANCE, MODULE

STATEMENT = "statement"
PARAM = "param"
KEYWORD = "keyword"


def describe_value(name, value):
    """(type, description) for a name bound to an inferred value (or None)."""
    if value is None:
        return STATEMENT, STATEMENT
    if value.kind == MODULE:
        return MODULE, f"module {name}"
    if value.kind == CLASS:
        return CLASS, f"class {name}"
    if value.kind == FUNCTION:
        return FUNCTION, f"def {name}(...)"
    if value.kind == INSTANCE and value.type_name:
        return INSTANCE, f"instance of {value.type_name}"
    return STATEMENT, STATEMENT


def describe_function(name):
    return FUNCTION, f"def {name}(...)"


def describe_class(name):
    return CLASS, f"class {name}"


def describe_module(name):
    return MODULE, f"module {name}"


def describe_param(name):
    return PARAM, f"param {name}"


def describe_keyword(name):
    return KEYWORD, name
"""Ordering of completion results."""


def name_group(name):
    """0 for public names, 1 for private (`_x`), 2 for dunders (`__x__`)."""
    if name.startswith("__") and name.endswith("__"):
        return 2
    if name.startswith("_"):
        return 1
    return 0


def sort_names(names):
    return sorted(names, key=lambda name: (name_group(name), name.lower(), name))


def sort_keywords(keywords):
    return sorted(keywords, key=lambda name: (name.lower(), name))
"""Prefix and fuzzy matching of completion names."""


def prefix_match(prefix, name):
    return name.lower().startswith(prefix.lower())


def fuzzy_match(query, name):
    """True when the characters of `query` appear in `name` in order."""
    remaining = iter(name.lower())
    return all(char in remaining for char in query.lower())


def make_matcher(prefix, fuzzy):
    if not prefix:
        return lambda name: True
    if fuzzy:
        return lambda name: fuzzy_match(prefix, name)
    return lambda name: prefix_match(prefix, name)
"""The builtin scope and Python keywords."""
import builtins
import keyword

from .entries import ValueEntry
from .values import wrap_runtime

KEYWORDS = tuple(keyword.kwlist)


def builtin_entries():
    """Entries for every name in the `builtins` module.

    Names that are also keywords (True, False, None) are offered only as
    keywords, so they are left out here.
    """
    entries = {}
    for name in dir(builtins):
        if keyword.iskeyword(name):
            continue
        entries[name] = ValueEntry(lambda name=name: wrap_runtime(getattr(builtins, name)))
    return entries
"""The completion engine: ties context, parsing, scopes and inference together."""
import ast
from dataclasses import asdict, dataclass

from . import context as cursor_context
from .builtin_scope import KEYWORDS
from .describe import describe_keyword
from .inference import Inferrer
from .locate import find_scope
from .matching import make_matcher
from .members import is_public
from .modules import Importer, ModuleContext
from .parsing import parse_tolerant
from .ranking import sort_keywords, sort_names
from .source import load_document
from .values import MODULE


@dataclass
class Completion:
    name: str
    complete: str
    type: str
    description: str

    def to_dict(self):
        return asdict(self)


def complete_file(path, line, col, fuzzy=False, project=None):
    """Completions for the cursor at 1-based `line`, 0-based `col` of `path`."""
    document = load_document(path)
    document.check_position(line, col)
    return Completer(document, line, col, fuzzy, project).run()


class Completer:
    def __init__(self, document, line, col, fuzzy, project=None):
        self.document = document
        self.line = line
        self.col = col
        self.fuzzy = fuzzy
        self.project = project

    def run(self):
        request = cursor_context.analyze(self.document.text_before(self.line, self.col))
        if request.kind == cursor_context.NONE:
            return []

        importer = Importer(self.project or self.document.directory, self.document.directory)
        tree = parse_tolerant(self.document.text, cursor=(self.line, self.col))
        module = ModuleContext(self.document.path, "__main__", tree, self.document.text)
        importer.register(module)
        inferrer = Inferrer(importer)
        scope = find_scope(module, self.line, self.col, self.document.lines[self.line - 1])

        if request.kind == cursor_context.ATTRIBUTE:
            entries = self._attribute_entries(inferrer, scope, request.receiver)
            keywords = []
        else:
            entries = inferrer.visible_entries(scope, self.line)
            keywords = KEYWORDS

        matches = make_matcher(request.prefix, self.fuzzy)
        cut = len(request.prefix)
        results = []
        for name in sort_names(n for n in entries if matches(n)):
            kind, description = entries[name].describe(name)
            results.append(Completion(name, name[cut:], kind, description))
        for name in sort_keywords(k for k in keywords if matches(k)):
            kind, description = describe_keyword(name)
            results.append(Completion(name, name[cut:], kind, description))
        return results

    def _attribute_entries(self, inferrer, scope, receiver):
        try:
            expression = ast.parse(receiver.strip(), mode="eval").body
        except (SyntaxError, ValueError):
            return {}
        line_text = self.document.lines[self.line - 1]
        position = (self.line, len(line_text[:self.col].encode("utf-8")))
        entries = {}
        for value in inferrer.infer_values(expression, scope, pos=position, strict=True):
            members = inferrer.members.all(value)
            if value.kind == MODULE:
                members = {name: entry for name, entry in members.items() if is_public(name)}
            for name, entry in members.items():
                entries.setdefault(name, entry)
        return entries
"""Textual analysis of the cursor position: prefix and completion kind."""
from dataclasses import dataclass

NAME = "name"
ATTRIBUTE = "attribute"
NONE = "none"

_OPENERS = {")": "(", "]": "[", "}": "{"}
_STRING_PREFIX_CHARS = "rRbBuUfF"


@dataclass
class CursorContext:
    """What kind of completion is requested and what has been typed so far."""

    kind: str
    prefix: str = ""
    receiver: str = ""


def is_identifier_char(char):
    return char == "_" or char.isalnum()


def analyze(text_before_cursor):
    """Classify the completion request from the source text before the cursor."""
    end = len(text_before_cursor)
    start = end
    while start > 0 and is_identifier_char(text_before_cursor[start - 1]):
        start -= 1
    prefix = text_before_cursor[start:]
    if prefix and prefix[0].isdigit():
        return CursorContext(NONE, prefix)

    before = text_before_cursor[:start]
    if not before.endswith("."):
        return CursorContext(NAME, prefix)

    receiver = extract_receiver(before[:-1])
    if not receiver or receiver.isdigit() or receiver.endswith("."):
        return CursorContext(NONE, prefix)
    return CursorContext(ATTRIBUTE, prefix, receiver)


def extract_receiver(text):
    """Return the expression text that ends at the end of `text`, or None."""
    i = len(text)
    while i > 0:
        char = text[i - 1]
        if char in _OPENERS:
            opener = _match_open(text, i - 1)
            if opener is None:
                return None
            i = opener
            continue
        if is_identifier_char(char):
            while i > 0 and is_identifier_char(text[i - 1]):
                i -= 1
            if i > 0 and text[i - 1] == ".":
                i -= 1
                continue
            break
        if char in "\"'":
            start = _string_start(text, i - 1)
            if start is None:
                return None
            i = start
            while i > 0 and text[i - 1] in _STRING_PREFIX_CHARS:
                i -= 1
            break
        break
    return text[i:].strip()


def _match_open(text, close_index):
    """Index of the bracket opening the one at `close_index`, scanning backwards."""
    stack = [text[close_index]]
    i = close_index - 1
    while i >= 0:
        char = text[i]
        if char in "\"'":
            start = _string_start(text, i)
            if start is None:
                return None
            i = start - 1
            continue
        if char in _OPENERS:
            stack.append(char)
        elif char in "([{":
            if _OPENERS[stack[-1]] != char:
                return None
            stack.pop()
            if not stack:
                return i
        i -= 1
    return None


def _string_start(text, end_index):
    """Index of the opening quote of the string literal ending at `end_index`."""
    quote = text[end_index]
    if end_index >= 2 and text[end_index - 2:end_index + 1] == quote * 3:
        start = text.rfind(quote * 3, 0, end_index - 2)
        return None if start < 0 else start
    i = end_index - 1
    while i >= 0:
        if text[i] == quote and (i == 0 or text[i - 1] != "\\"):
            return i
        if text[i] == "\n":
            return None
        i -= 1
    return None

"""Error-tolerant parsing of Python source into an AST.

Syntax errors are repaired line by line: the offending line is replaced by a
sequence of progressively more conservative candidates (a placeholder name at
the cursor, `pass`, and finally a blank line) until the module parses.  Lines
are never inserted or removed, so AST line numbers match the original file.
"""
import ast
import re
import time
import warnings

# Identifier inserted at the cursor to make incomplete expressions parseable.
# Bindings whose names contain it are ignored by scope analysis.
PLACEHOLDER = "__sith_cursor__"

# After this many seconds of repairs, everything from the error onward is dropped.
_TIME_BUDGET = 1.0
_INDENTATION_ERRORS = ("unindent does not match", "unexpected indent")
_INDENTED_BLOCK = re.compile(r"expected an indented block after .* on line (\d+)")

_CLOSERS = {"(": ")", "[": "]", "{": "}"}
# Keywords that can never appear inside a bracketed expression.
_STATEMENT_KEYWORDS = {
    "def", "class", "return", "import", "pass", "break", "continue", "raise", "del",
    "global", "nonlocal", "assert", "while", "with", "try", "except", "finally", "elif",
}
# Keywords that, at or below the opening line's indentation, start a new statement.
_BLOCK_KEYWORDS = {"if", "for", "else", "async", "from", "match", "case"}
_FIRST_WORD = re.compile(r"[A-Za-z_]\w*")


def parse_tolerant(text, cursor=None):
    """Parse `text`, repairing syntax errors. `cursor` is (line, col) or None."""
    lines = close_brackets(text.replace("\0", " ").split("\n"))
    return _Repairer(lines, cursor).run()


def close_brackets(lines):
    """Close brackets left open when a new statement evidently begins.

    An unclosed bracket otherwise swallows every following line, and the
    parser then blames those (valid) lines instead of the incomplete one.
    """
    lines = list(lines)
    stack = []  # (bracket, line index)
    triple = None
    for index, line in enumerate(lines):
        if stack and triple is None and _starts_statement(line, lines[stack[0][1]]):
            _append_closers(lines, stack, index)
        triple = _scan_brackets(line, stack, triple, index)
    if stack and triple is None:
        _append_closers(lines, stack, len(lines))
    return lines


def _starts_statement(line, opener_line):
    code = line.strip()
    if not code or code.startswith("#"):
        return False
    indent = len(_indent_of(line))
    opener_indent = len(_indent_of(opener_line))
    match = _FIRST_WORD.match(code)
    word = match.group(0) if match else ""
    if word in _STATEMENT_KEYWORDS:
        return True
    if indent <= opener_indent and (word in _BLOCK_KEYWORDS or code.startswith("@")):
        return True
    return indent < opener_indent and code[0] not in ")]}"


def _append_closers(lines, stack, before):
    """Append closers for `stack` to the last code line before index `before`."""
    for index in range(before - 1, stack[0][1] - 1, -1):
        code = strip_comment(lines[index]).rstrip()
        if code.strip():
            lines[index] = code + "".join(_CLOSERS[b] for b, _ in reversed(stack))
            break
    stack.clear()


def _scan_brackets(line, stack, triple, index):
    """Update the bracket stack with `line`; returns the open triple quote, if any."""
    i = 0
    while i < len(line):
        if triple is not None:
            end = line.find(triple, i)
            if end < 0:
                return triple
            i = end + 3
            triple = None
            continue
        char = line[i]
        if char == "#":
            break
        if char in "\"'":
            if line.startswith(char * 3, i):
                triple = char * 3
                i += 3
                continue
            i += 1
            while i < len(line) and line[i] != char:
                i += 2 if line[i] == "\\" else 1
        elif char in _CLOSERS:
            stack.append((char, index))
        elif char in ")]}" and stack and _CLOSERS[stack[-1][0]] == char:
            stack.pop()
        i += 1
    return triple


def strip_comment(line):
    """Remove a trailing `#` comment, ignoring `#` inside string literals."""
    quote = None
    i = 0
    while i < len(line):
        char = line[i]
        if quote:
            if char == "\\":
                i += 1
            elif char == quote:
                quote = None
        elif char in "\"'":
            quote = char
        elif char == "#":
            return line[:i]
        i += 1
    return line


def _neighbour_indent(lines):
    """Indentation of the first code line in `lines`, or None."""
    for line in lines:
        if line.strip() and not line.strip().startswith("#"):
            return len(_indent_of(line))
    return None


def _indent_of(line):
    return line[: len(line) - len(line.lstrip())]


class _Repairer:
    def __init__(self, lines, cursor):
        self.original = lines
        self.state = list(lines)
        self.cursor = cursor
        self.candidates = {}
        self.positions = {}
        self.pass_appended = set()
        self.string_closed = False
        self.truncated = False
        self.deadline = None

    def run(self):
        limit = 4 * len(self.state) + 20
        self.deadline = time.monotonic() + _TIME_BUDGET
        with warnings.catch_warnings():
            warnings.simplefilter("ignore")
            for _ in range(limit):
                try:
                    return ast.parse("\n".join(self.state))
                except (SyntaxError, ValueError) as error:
                    if not self._repair(error):
                        break
        return ast.Module(body=[], type_ignores=[])

    def _repair(self, error):
        count = len(self.state)
        line = getattr(error, "lineno", None) or count
        line = max(1, min(line, count))
        message = str(getattr(error, "msg", ""))
        if "unterminated triple-quoted string" in message and self._close_string(error, line):
            return True
        if not self.truncated and time.monotonic() > self.deadline:
            self._drop_from(line)
            return True
        match = _INDENTED_BLOCK.search(message)
        if match:
            if self._is_cursor_line(line) and self._advance(line):
                return True
            if self._append_pass(int(match.group(1)), line):
                return True
        if any(text in message for text in _INDENTATION_ERRORS) and self._blank(line):
            return True
        if self._advance(line):
            return True
        for previous in range(line - 1, 0, -1):
            if self._advance(previous):
                return True
        return False

    def _is_cursor_line(self, line):
        return self.cursor is not None and self.cursor[0] == line

    def _drop_from(self, line):
        """Give up on the rest of the file: blank every line from `line` on."""
        for index in range(line - 1, len(self.state)):
            self.state[index] = ""
            self._line_candidates(index + 1)
            self.positions[index + 1] = len(self.candidates[index + 1]) - 1
        self.truncated = True

    def _blank(self, line):
        """Jump straight to the blank candidate (indentation cannot be fixed in place)."""
        options = self._line_candidates(line)
        if self.state[line - 1] == "":
            return False
        self.positions[line] = len(options) - 1
        self.state[line - 1] = ""
        return True

    def _close_string(self, error, line):
        """Terminate a triple-quoted string that runs to the end of the file."""
        offset = (getattr(error, "offset", None) or 1) - 1
        quote = self.state[line - 1][offset:offset + 3]
        if quote not in ('"""', "'''") or self.string_closed:
            return False
        self.state[-1] += " " + quote
        self.string_closed = True
        return True

    def _append_pass(self, header_line, error_line):
        """Give a block header with a missing body an inline `pass` body."""
        last = min(max(error_line, header_line), len(self.state))
        for line in range(last, header_line - 1, -1):
            code = strip_comment(self.state[line - 1]).rstrip()
            if code.endswith(":") and line not in self.pass_appended:
                self.state[line - 1] = code + " pass"
                self.pass_appended.add(line)
                return True
        return False

    def _line_candidates(self, line):
        if line not in self.candidates:
            text = self.original[line - 1]
            indent = _indent_of(text)
            options = [text]
            if self._is_cursor_line(line):
                col = min(self.cursor[1], len(text))
                options.append(text[:col] + PLACEHOLDER + text[col:])
                options.append(text[:col] + PLACEHOLDER)
            if self._out_of_place(line, text):
                options.append("")
            header = self._header_replacement(line, text)
            if header:
                options.append(header)
            options += [indent + "pass", ""]
            unique = []
            for option in options:
                if option not in unique:
                    unique.append(option)
            self.candidates[line] = unique
            self.positions[line] = 0
        return self.candidates[line]

    def _out_of_place(self, line, text):
        """True for a line dedented below both its neighbouring code lines."""
        indent = len(_indent_of(text))
        before = _neighbour_indent(reversed(self.original[: line - 1]))
        after = _neighbour_indent(self.original[line:])
        return before is not None and after is not None and indent < min(before, after)

    def _header_replacement(self, line, text):
        """A valid block header for a broken line that is followed by a block.

        Keeping a header lets the indented body that follows still parse,
        instead of failing line by line with "unexpected indent".
        """
        indent = _indent_of(text)
        for following in self.original[line:]:
            if following.strip() and not following.strip().startswith("#"):
                if len(_indent_of(following)) <= len(indent):
                    return None
                break
        else:
            return None
        word = (_FIRST_WORD.match(text.strip()) or [""])[0]
        if word in ("def", "async"):
            return f"{indent}def {PLACEHOLDER}():"
        if word == "class":
            return f"{indent}class {PLACEHOLDER}:"
        return f"{indent}if True:"

    def _advance(self, line):
        """Switch `line` to its next repair candidate; False when exhausted."""
        options = self._line_candidates(line)
        position = self.positions[line]
        while position + 1 < len(options):
            position += 1
            if options[position] != self.state[line - 1]:
                self.positions[line] = position
                self.state[line - 1] = options[position]
                return True
        self.positions[line] = position
        return False
"""Finding the innermost scope that contains the cursor."""
import ast

from .scopes import COMPREHENSION, LAMBDA

_DEFINITIONS = (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)


def cursor_indent(line_text, col):
    """Indentation that governs the cursor's block membership."""
    before = line_text[:col]
    if not before.strip():
        return len(before)
    return len(line_text) - len(line_text.lstrip())


def find_scope(context, line, col, line_text):
    """The innermost Scope of `context` enclosing the cursor at (line, col)."""
    byte_col = len(line_text[:col].encode("utf-8"))
    indent = cursor_indent(line_text, col)
    scope = context.root
    for node in _definition_chain(context.tree.body, line, byte_col, indent):
        scope = context.scope_of(node) or scope
    return _innermost_expression_scope(scope, line, byte_col)


def _definition_chain(statements, line, byte_col, indent):
    """def/class nodes whose bodies contain the cursor, outermost first."""
    chain = []
    while True:
        candidate = None
        for statement in statements:
            if statement.lineno <= line:
                candidate = statement
            else:
                break
        if candidate is None:
            return chain
        inside = line <= candidate.end_lineno or indent > candidate.col_offset
        if not inside:
            return chain
        if isinstance(candidate, _DEFINITIONS):
            if not _in_body(candidate, line, byte_col):
                return chain
            chain.append(candidate)
            statements = candidate.body
        else:
            statements = _child_statements(candidate)
            if not statements:
                return chain


def _in_body(node, line, byte_col):
    first = node.body[0]
    if line > _header_end(node):
        return True
    return line == first.lineno and byte_col >= first.col_offset


def _header_end(node):
    parts = []
    if isinstance(node, ast.ClassDef):
        parts = node.bases + [k.value for k in node.keywords]
    else:
        args = node.args
        parts = args.posonlyargs + args.args + args.kwonlyargs + args.defaults
        parts += [d for d in args.kw_defaults if d is not None]
        parts += [a for a in (args.vararg, args.kwarg, node.returns) if a is not None]
    return max([node.lineno] + [getattr(p, "end_lineno", None) or node.lineno for p in parts])


def _child_statements(node):
    children = []
    for field in ("body", "orelse", "finalbody"):
        children += [s for s in getattr(node, field, []) if isinstance(s, ast.stmt)]
    for handler in getattr(node, "handlers", []):
        children += handler.body
    for case in getattr(node, "cases", []):
        children += case.body
    return sorted(children, key=lambda s: (s.lineno, s.col_offset))


def _contains(node, line, byte_col):
    start = (node.lineno, node.col_offset)
    end = (node.end_lineno, node.end_col_offset)
    return start <= (line, byte_col) <= end


def _innermost_expression_scope(scope, line, byte_col):
    """Descend into lambda/comprehension scopes that contain the cursor."""
    while True:
        for child in scope.children:
            if child.kind in (LAMBDA, COMPREHENSION) and _contains(child.node, line, byte_col):
                scope = child
                break
        else:
            return scope
"""Inferred values: what an expression evaluates to, statically."""
import inspect

MODULE = "module"
CLASS = "class"
FUNCTION = "function"
INSTANCE = "instance"


class Value:
    kind = None

    @property
    def type_name(self):
        return None

    @property
    def key(self):
        """Identity used to de-duplicate unions of inferred values."""
        return (type(self).__name__, id(self._identity()))

    def _identity(self):
        return self


class LocalModule(Value):
    """A module parsed from a project source file."""

    kind = MODULE

    def __init__(self, context):
        self.context = context

    def _identity(self):
        return self.context


class RuntimeModule(Value):
    """An installed module, imported for introspection."""

    kind = MODULE

    def __init__(self, obj):
        self.obj = obj

    def _identity(self):
        return self.obj


class LocalClass(Value):
    """A class defined by a `class` statement in parsed source."""

    kind = CLASS

    def __init__(self, scope):
        self.scope = scope

    def _identity(self):
        return self.scope

    @property
    def node(self):
        return self.scope.node

    @property
    def name(self):
        return self.scope.node.name


class LocalFunction(Value):
    """A `def` or `lambda` from parsed source, optionally bound to `self`/`cls`."""

    kind = FUNCTION

    def __init__(self, scope, bound=None):
        self.scope = scope
        self.bound = bound

    def _identity(self):
        return self.scope

    @property
    def node(self):
        return self.scope.node


class LocalInstance(Value):
    """An instance of a local class; `init_args` maps `__init__` parameters to values."""

    kind = INSTANCE

    def __init__(self, cls, init_args=None):
        self.cls = cls
        self.init_args = init_args

    def _identity(self):
        return self.cls.scope

    @property
    def type_name(self):
        return self.cls.name


class RuntimeClass(Value):
    kind = CLASS

    def __init__(self, obj):
        self.obj = obj

    def _identity(self):
        return self.obj


class RuntimeFunction(Value):
    kind = FUNCTION

    def __init__(self, obj):
        self.obj = obj

    def _identity(self):
        return self.obj


class RuntimeInstance(Value):
    """An instance of a runtime class (also used for literals)."""

    kind = INSTANCE

    def __init__(self, cls):
        self.cls = cls

    def _identity(self):
        return self.cls

    @property
    def type_name(self):
        return self.cls.__name__


def unique(values):
    """`values` without duplicates (by identity key), in order."""
    seen = set()
    result = []
    for value in values:
        if value is not None and value.key not in seen:
            seen.add(value.key)
            result.append(value)
    return result


def wrap_runtime(obj):
    """Wrap a live Python object as a Value (None for opaque data descriptors)."""
    if inspect.ismodule(obj):
        return RuntimeModule(obj)
    if inspect.isclass(obj):
        return RuntimeClass(obj)
    origin = getattr(obj, "__origin__", None)
    if inspect.isclass(origin):  # generic aliases such as typing.List or list[int]
        return RuntimeClass(origin)
    if callable(obj):
        return RuntimeFunction(obj)
    if inspect.isdatadescriptor(obj):
        return None
    return RuntimeInstance(type(obj))


# Builtin types whose attributes are introspected on a real (empty) instance,
# so that e.g. `(1).real` is known to be an int rather than a descriptor.
_SAMPLE_TYPES = (bool, int, float, complex, str, bytes, bytearray, list, tuple, dict, set,
                 frozenset, type(None))


def runtime_sample(cls):
    """An instance of `cls` to introspect, or the class itself."""
    if cls in _SAMPLE_TYPES:
        return cls()
    return cls

"""Definition records reported by `infer` and `goto`."""
import ast
import inspect
import os
import re
import sys
from dataclasses import asdict, dataclass

from .inference import BuiltinBinding
from .scopes import CLASS, FUNCTION, Binding
from .values import (
    LocalClass,
    LocalFunction,
    LocalInstance,
    LocalModule,
    RuntimeClass,
    RuntimeFunction,
    RuntimeInstance,
    RuntimeModule,
)

_DEFINITION_HEADER = re.compile(r"(?:async\s+)?(?:def|class)\s+")


@dataclass
class Definition:
    name: str
    type: str
    full_name: str
    module_path: str
    line: int
    column: int
    description: str
    docstring: str

    def to_dict(self):
        return asdict(self)

    @property
    def sort_key(self):
        return (self.module_path, self.line, self.column)


def sorted_unique(definitions):
    """Definitions without duplicates, sorted by (module_path, line, column)."""
    seen = set()
    result = []
    for definition in definitions:
        if definition is None:
            continue
        identity = tuple(definition.to_dict().items())
        if identity not in seen:
            seen.add(identity)
            result.append(definition)
    return sorted(result, key=lambda d: d.sort_key)


def normalize(text):
    return re.sub(r"\s+", " ", text).strip()


def char_column(context, line, byte_col):
    """Convert a UTF-8 byte offset on `line` to a character offset."""
    if not 1 <= line <= len(context.lines):
        return byte_col
    encoded = context.lines[line - 1].encode("utf-8")
    return len(encoded[:byte_col].decode("utf-8", errors="ignore"))


def find_word(text, word, start=0):
    """Column of the identifier `word` in `text` at or after `start`, or None."""
    match = re.compile(r"(?<![\w])" + re.escape(word) + r"(?![\w])").search(text, max(start, 0))
    return match.start() if match else None


class DefinitionFactory:
    """Builds Definition records for bindings and inferred values."""

    def __init__(self, inferrer, project_root):
        self.inferrer = inferrer
        self.project_root = os.path.abspath(project_root)

    # -- modules and paths -----------------------------------------------------

    def relative_path(self, path):
        if not path:
            return ""
        path = os.path.abspath(path)
        try:
            relative = os.path.relpath(path, self.project_root)
        except ValueError:
            return path
        if relative == os.pardir or relative.startswith(os.pardir + os.sep):
            return path
        return relative

    def module_name(self, context):
        """Dotted module name of a parsed file, relative to the project root."""
        if not context.path:
            return context.name
        relative = self.relative_path(context.path)
        if os.path.isabs(relative):
            if context.name and context.name != "__main__":
                return context.name
            relative = os.path.basename(relative)
        stem = os.path.splitext(relative)[0]
        parts = [p for p in stem.split(os.sep) if p]
        if len(parts) > 1 and parts[-1] == "__init__":
            parts.pop()
        return ".".join(parts)

    def qualified_name(self, scope):
        """Dotted name of a scope: module, then enclosing classes and functions."""
        parts = []
        for current in scope.chain():
            if current.kind in (CLASS, FUNCTION):
                parts.append(current.node.name)
        parts.append(self.module_name(scope.module))
        return ".".join(reversed(parts))

    # -- source helpers --------------------------------------------------------

    @staticmethod
    def source(context, node):
        text = None
        try:
            text = ast.get_source_segment(context.text, node)
        except Exception:
            text = None
        if not text:
            try:
                text = ast.unparse(node)
            except Exception:
                text = ""
        return normalize(text)

    def parameters(self, context, arguments):
        """The parameter list of a function, formatted like its source."""

        def param(arg, default=None):
            text = arg.arg
            if arg.annotation is not None:
                text += ": " + self.source(context, arg.annotation)
            if default is not None:
                separator = " = " if arg.annotation is not None else "="
                text += separator + self.source(context, default)
            return text

        parts = []
        positional = arguments.posonlyargs + arguments.args
        defaults = [None] * (len(positional) - len(arguments.defaults)) + list(arguments.defaults)
        for index, arg in enumerate(positional):
            parts.append(param(arg, defaults[index]))
            if arguments.posonlyargs and index == len(arguments.posonlyargs) - 1:
                parts.append("/")
        if arguments.vararg is not None:
            parts.append("*" + param(arguments.vararg))
        elif arguments.kwonlyargs:
            parts.append("*")
        for arg, default in zip(arguments.kwonlyargs, arguments.kw_defaults):
            parts.append(param(arg, default))
        if arguments.kwarg is not None:
            parts.append("**" + param(arguments.kwarg))
        return ", ".join(parts)

    # -- bindings ----------------------------------------------------------------

    def from_source(self, source):
        """A Definition for a Binding, BuiltinBinding or Value."""
        if isinstance(source, BuiltinBinding):
            return self.from_value(source.value())
        if isinstance(source, Binding):
            return self.from_binding(source)
        return self.from_value(source)

    def from_binding(self, binding):
        context = binding.scope.module
        line, column = self.binding_position(binding)
        owner = binding.extra.get("owner")
        if owner is not None:
            full_name = f"{self.qualified_name(owner)}.{binding.name}"
        else:
            full_name = f"{self.qualified_name(binding.scope)}.{binding.name}"
        docstring = ""
        if binding.kind in ("def", "class"):
            docstring = ast.get_docstring(binding.node) or ""
        return Definition(
            name=binding.name,
            type=self.binding_type(binding),
            full_name=full_name,
            module_path=self.relative_path(context.path),
            line=line,
            column=column,
            description=self.binding_description(binding),
            docstring=docstring,
        )

    def binding_type(self, binding):
        kind = binding.kind
        if kind == "def":
            return "function"
        if kind == "class":
            return "class"
        if kind == "param":
            return "param"
        if kind == "import":
            return "module"
        if kind == "importfrom":
            values = self.inferrer.binding_values(binding)
            if values and values[0].kind:
                return values[0].kind
            return "module"
        return "statement"

    def binding_description(self, binding):
        context = binding.scope.module
        node = binding.node
        kind = binding.kind
        if kind == "def":
            return f"def {node.name}({self.parameters(context, node.args)})"
        if kind == "class":
            return f"class {node.name}"
        if kind == "param":
            return f"param {binding.name}"
        if kind in ("import", "importfrom"):
            return normalize(ast.unparse(node))
        if kind == "assign":
            if isinstance(node, (ast.Assign, ast.NamedExpr)) or (
                    isinstance(node, ast.AnnAssign) and node.value is not None):
                return self.source(context, node.value)
            return self.source(context, node)
        if kind in ("loop", "comprehension"):
            return f"for {self.source(context, node.target)} in {self.source(context, node.iter)}"
        if kind == "with":
            items = ", ".join(self.source(context, item) for item in node.items)
            return f"with {items}"
        if kind == "except":
            if node.type is None:
                return "except"
            return f"except {self.source(context, node.type)} as {binding.name}"
        if kind == "pattern":
            return f"case {self.source(context, node.pattern)}"
        return self.source(context, node)

    def binding_position(self, binding):
        """(1-based line, 0-based character column) of the bound identifier."""
        context = binding.scope.module
        target = binding.target
        node = binding.node
        lines = context.lines

        def text(line):
            return lines[line - 1] if 1 <= line <= len(lines) else ""

        if isinstance(target, (ast.Name, ast.arg)):
            return target.lineno, char_column(context, target.lineno, target.col_offset)
        if isinstance(target, ast.Attribute):
            end = char_column(context, target.end_lineno, target.end_col_offset)
            return target.end_lineno, end - len(target.attr)
        if isinstance(target, ast.alias):
            start = char_column(context, target.lineno, target.col_offset)
            if target.asname:
                found = find_word(text(target.lineno), target.asname, start + len(target.name))
                if found is not None:
                    return target.lineno, found
            return target.lineno, start
        if binding.kind in ("def", "class"):
            start = char_column(context, node.lineno, node.col_offset)
            match = _DEFINITION_HEADER.match(text(node.lineno), start)
            if match:
                return node.lineno, match.end()
            return node.lineno, start
        if binding.kind == "except":
            for line in range(node.lineno, (node.body[0].lineno if node.body else node.lineno) + 1):
                match = re.search(r"\bas\s+(" + re.escape(binding.name) + r")\b", text(line))
                if match:
                    return line, match.start(1)
        if isinstance(target, ast.pattern):
            for line in range(target.lineno, target.end_lineno + 1):
                start = char_column(context, line, target.col_offset) if line == target.lineno else 0
                found = find_word(text(line), binding.name, start)
                if found is not None:
                    return line, found
        if binding.kind == "importfrom" and isinstance(node, ast.ImportFrom):
            star = text(node.lineno).find("*")
            if star >= 0:
                return node.lineno, star
        found = find_word(text(binding.line), binding.name)
        return binding.line, found if found is not None else 0

    # -- values --------------------------------------------------------------------

    def from_value(self, value):
        if value is None:
            return None
        if isinstance(value, (LocalFunction, LocalClass)):
            return self._local_definition(value)
        if isinstance(value, LocalInstance):
            definition = self._local_definition(value.cls)
            if definition is None:
                return None
            definition.type = "instance"
            definition.description = f"instance of {value.cls.name}"
            return definition
        if isinstance(value, LocalModule):
            context = value.context
            name = self.module_name(context)
            return Definition(
                name=name.split(".")[-1],
                type="module",
                full_name=name,
                module_path=self.relative_path(context.path),
                line=1,
                column=0,
                description=f"module {name.split('.')[-1]}",
                docstring=ast.get_docstring(context.tree) or "",
            )
        if isinstance(value, RuntimeModule):
            return self._runtime_module(value.obj)
        if isinstance(value, RuntimeClass):
            return self._runtime_definition(value.obj, "class")
        if isinstance(value, RuntimeFunction):
            return self._runtime_definition(value.obj, "function")
        if isinstance(value, RuntimeInstance):
            return self._runtime_definition(value.cls, "instance")
        return None

    def _local_definition(self, value):
        node = value.scope.node
        context = value.scope.module
        if isinstance(node, ast.Lambda):
            parameters = self.parameters(context, node.args)
            return Definition(
                name="<lambda>",
                type="function",
                full_name=f"{self.qualified_name(value.scope.parent)}.<lambda>",
                module_path=self.relative_path(context.path),
                line=node.lineno,
                column=char_column(context, node.lineno, node.col_offset),
                description=f"def <lambda>({parameters})",
                docstring="",
            )
        binding = context.binding_of(node)
        if binding is None:
            return None
        return self.from_binding(binding)

    def _runtime_module(self, module):
        name = getattr(module, "__name__", "") or ""
        path = getattr(module, "__file__", None) or ""
        if path.endswith((".pyc", ".pyo")):
            path = path[:-1]
        if path and not path.endswith(".py"):
            path = ""
        return Definition(
            name=name.split(".")[-1],
            type="module",
            full_name=name,
            module_path=self.relative_path(path),
            line=1 if path else 0,
            column=0,
            description=f"module {name.split('.')[-1]}",
            docstring=_docstring(module),
        )

    def _runtime_definition(self, obj, kind):
        name = getattr(obj, "__name__", None) or type(obj).__name__
        qualname = getattr(obj, "__qualname__", None) or name
        module = getattr(obj, "__module__", None)
        if not isinstance(module, str):
            owner = getattr(obj, "__objclass__", None) or getattr(getattr(obj, "__self__", None), "__class__", None)
            module = getattr(owner, "__module__", None) if owner is not None else None
        module = module or "builtins"
        builtin = module == "builtins"
        path, line, column = ("", 0, 0) if builtin else _runtime_location(obj, name)
        if kind == "class":
            description = f"class {name}"
        elif kind == "instance":
            description = f"instance of {name}"
        else:
            description = f"def {name}({_runtime_parameters(obj)})"
        return Definition(
            name=name,
            type=kind,
            full_name=f"{module}.{qualname}",
            module_path=self.relative_path(path),
            line=line,
            column=column,
            description=description,
            docstring="" if builtin else _docstring(obj),
        )


def _docstring(obj):
    try:
        return inspect.getdoc(obj) or ""
    except Exception:
        return ""


def _runtime_parameters(obj):
    try:
        signature = inspect.signature(obj)
    except (TypeError, ValueError):
        return "..."
    text = str(signature.replace(return_annotation=inspect.Signature.empty))
    return text[1:-1]


def _runtime_location(obj, name):
    """(path, line, column) of a runtime class or function's source, if available."""
    path = ""
    module = sys.modules.get(getattr(obj, "__module__", None) or "")
    module_file = getattr(module, "__file__", None) or ""
    if module_file.endswith(".py"):
        path = module_file
    try:
        source_file = inspect.getsourcefile(obj)
        lines, start = inspect.getsourcelines(obj)
    except (TypeError, OSError):
        return path, 0, 0
    if not source_file:
        return path, 0, 0
    for offset, text in enumerate(lines):
        match = re.search(r"(?:def|class)\s+(" + re.escape(name) + r")\b", text)
        if match:
            return source_file, start + offset, match.start(1)
    return source_file, start, 0
"""Scope analysis: which names each scope binds, and where."""
import ast
from dataclasses import dataclass, field

from .parsing import PLACEHOLDER

MODULE = "module"
FUNCTION = "function"
CLASS = "class"
LAMBDA = "lambda"
COMPREHENSION = "comprehension"

_FUNCTION_NODES = (ast.FunctionDef, ast.AsyncFunctionDef)
_COMPREHENSION_NODES = (ast.ListComp, ast.SetComp, ast.DictComp, ast.GeneratorExp)


@dataclass(eq=False)
class Binding:
    """A single place where a name is bound."""

    name: str
    line: int
    kind: str
    node: ast.AST
    scope: "Scope"
    value: ast.AST = None
    extra: dict = field(default_factory=dict)
    # The node naming the bound identifier (ast.Name, ast.arg, ast.alias, ...).
    target: ast.AST = None


@dataclass(eq=False)
class StarImport:
    """A `from module import *` statement."""

    module: str
    level: int
    line: int
    scope: "Scope"
    node: ast.AST = None


class Scope:
    """A namespace: module, function, class, lambda or comprehension."""

    def __init__(self, kind, node, parent, module):
        self.kind = kind
        self.node = node
        self.parent = parent
        self.module = module
        self.bindings = {}
        self.star_imports = []
        self.children = []
        self.global_names = set()
        self.local_node_ids = None  # ids of the nodes of the body, cached by flow analysis
        self.nonlocal_names = set()
        if parent is not None:
            parent.children.append(self)

    def add(self, binding):
        self.bindings.setdefault(binding.name, []).append(binding)

    def chain(self):
        """This scope followed by all its ancestors."""
        scope = self
        while scope is not None:
            yield scope
            scope = scope.parent

    def root(self):
        scope = self
        while scope.parent is not None:
            scope = scope.parent
        return scope


def iter_target_names(target, value):
    """Yield (Name node, value expression or None) pairs for an assignment target."""
    if isinstance(target, ast.Name):
        yield target, value
    elif isinstance(target, (ast.Tuple, ast.List)):
        values = None
        if (
            isinstance(value, (ast.Tuple, ast.List))
            and len(value.elts) == len(target.elts)
            and not any(isinstance(e, ast.Starred) for e in target.elts + value.elts)
        ):
            values = value.elts
        for index, element in enumerate(target.elts):
            yield from iter_target_names(element, values[index] if values else None)
    elif isinstance(target, ast.Starred):
        yield from iter_target_names(target.value, None)


def function_parameters(arguments):
    """All parameter `arg` nodes of an `ast.arguments`, in declaration order."""
    params = list(arguments.posonlyargs) + list(arguments.args)
    if arguments.vararg:
        params.append(arguments.vararg)
    params += list(arguments.kwonlyargs)
    if arguments.kwarg:
        params.append(arguments.kwarg)
    return params


def walk_local(statements):
    """Walk nodes of a body without descending into nested scopes."""
    stack = list(reversed(statements))
    while stack:
        node = stack.pop()
        yield node
        if isinstance(node, _FUNCTION_NODES + (ast.ClassDef, ast.Lambda)):
            continue
        stack.extend(reversed(list(ast.iter_child_nodes(node))))


def _declared(statements, kind):
    """Names declared `global`/`nonlocal` directly in a function body."""
    names = set()
    stack = list(statements)
    while stack:
        node = stack.pop()
        if isinstance(node, kind):
            names.update(node.names)
        if isinstance(node, _FUNCTION_NODES + (ast.ClassDef, ast.Lambda)):
            continue
        stack.extend(ast.iter_child_nodes(node))
    return names


class ScopeBuilder:
    """Walks a module AST and builds its tree of scopes."""

    def __init__(self, module_context):
        self.module_context = module_context
        self.scope_by_node = {}
        self.binding_by_target = {}

    def build(self, tree):
        root = self._new_scope(MODULE, tree, None)
        self._statements(root, tree.body)
        return root

    def _new_scope(self, kind, node, parent):
        scope = Scope(kind, node, parent, self.module_context)
        self.scope_by_node[id(node)] = scope
        return scope

    # -- binding helpers -------------------------------------------------

    def _bind(self, scope, name, line, kind, node, value=None, target=None, **extra):
        if PLACEHOLDER in name:
            return
        if scope.kind == FUNCTION:
            if name in scope.nonlocal_names:
                return
            if name in scope.global_names:
                scope = scope.root()
        binding = Binding(name, line, kind, node, scope, value, extra, target)
        scope.add(binding)
        self.binding_by_target.setdefault(id(target if target is not None else node), binding)

    def _bind_target(self, scope, target, kind, value, node, **extra):
        for name_node, element_value in iter_target_names(target, value):
            self._bind(scope, name_node.id, name_node.lineno, kind, node, element_value,
                       target=name_node, **extra)
        for child in ast.walk(target):
            if isinstance(child, (ast.Attribute, ast.Subscript)):
                self._expression(scope, child)

    def _bind_arguments(self, scope, function_node):
        for index, param in enumerate(function_parameters(function_node.args)):
            self._bind(scope, param.arg, function_node.lineno, "param", function_node,
                       target=param, arg=param, index=index)

    # -- statements --------------------------------------------------------

    def _statements(self, scope, statements):
        for statement in statements:
            self._statement(scope, statement)

    def _statement(self, scope, node):
        handler = getattr(self, "_stmt_" + type(node).__name__, None)
        if handler is not None:
            handler(scope, node)
            return
        for child in ast.iter_child_nodes(node):
            if isinstance(child, ast.stmt):
                self._statement(scope, child)
            else:
                self._expression(scope, child)

    def _stmt_FunctionDef(self, scope, node):
        for expression in node.decorator_list + node.args.defaults + node.args.kw_defaults:
            self._expression(scope, expression)
        for param in function_parameters(node.args):
            self._expression(scope, param.annotation)
        self._expression(scope, node.returns)
        self._bind(scope, node.name, node.lineno, "def", node)
        child = self._new_scope(FUNCTION, node, scope)
        child.global_names = _declared(node.body, ast.Global)
        child.nonlocal_names = _declared(node.body, ast.Nonlocal)
        self._bind_arguments(child, node)
        self._statements(child, node.body)

    _stmt_AsyncFunctionDef = _stmt_FunctionDef

    def _stmt_ClassDef(self, scope, node):
        for expression in node.decorator_list + node.bases + [k.value for k in node.keywords]:
            self._expression(scope, expression)
        self._bind(scope, node.name, node.lineno, "class", node)
        child = self._new_scope(CLASS, node, scope)
        self._statements(child, node.body)

    def _stmt_Assign(self, scope, node):
        self._expression(scope, node.value)
        for target in node.targets:
            self._bind_target(scope, target, "assign", node.value, node)

    def _stmt_AnnAssign(self, scope, node):
        self._expression(scope, node.value)
        self._expression(scope, node.annotation)
        if isinstance(node.target, ast.Name):
            self._bind(scope, node.target.id, node.target.lineno, "assign", node, node.value,
                       target=node.target, annotation=node.annotation)
        else:
            self._expression(scope, node.target)

    def _stmt_AugAssign(self, scope, node):
        self._expression(scope, node.value)
        target = node.target
        if isinstance(target, ast.Name):
            if target.id not in scope.bindings:
                self._bind(scope, target.id, target.lineno, "augassign", node, target=target)
        else:
            self._expression(scope, target)

    def _stmt_For(self, scope, node):
        self._expression(scope, node.iter)
        self._bind_target(scope, node.target, "loop", None, node)
        self._statements(scope, node.body)
        self._statements(scope, node.orelse)

    _stmt_AsyncFor = _stmt_For

    def _stmt_With(self, scope, node):
        for item in node.items:
            self._expression(scope, item.context_expr)
            if item.optional_vars is not None:
                self._bind_target(scope, item.optional_vars, "with", None, node,
                                  context=item.context_expr)
        self._statements(scope, node.body)

    _stmt_AsyncWith = _stmt_With

    def _stmt_Try(self, scope, node):
        self._statements(scope, node.body)
        for handler in node.handlers:
            self._expression(scope, handler.type)
            if handler.name:
                self._bind(scope, handler.name, handler.lineno, "except", handler,
                           exception=handler.type)
            self._statements(scope, handler.body)
        self._statements(scope, node.orelse)
        self._statements(scope, node.finalbody)

    _stmt_TryStar = _stmt_Try

    def _stmt_Match(self, scope, node):
        self._expression(scope, node.subject)
        for case in node.cases:
            for pattern in ast.walk(case.pattern):
                for attribute in ("name", "rest"):
                    name = getattr(pattern, attribute, None)
                    if isinstance(name, str):
                        self._bind(scope, name, pattern.lineno, "pattern", case, target=pattern)
                if isinstance(pattern, ast.MatchValue):
                    self._expression(scope, pattern.value)
            self._expression(scope, case.guard)
            self._statements(scope, case.body)

    def _stmt_Import(self, scope, node):
        for alias in node.names:
            if alias.asname:
                self._bind(scope, alias.asname, node.lineno, "import", node, target=alias,
                           module=alias.name)
            else:
                top = alias.name.split(".")[0]
                self._bind(scope, top, node.lineno, "import", node, target=alias, module=top)

    def _stmt_ImportFrom(self, scope, node):
        for alias in node.names:
            if alias.name == "*":
                scope.star_imports.append(
                    StarImport(node.module or "", node.level, node.lineno, scope, node))
            else:
                self._bind(scope, alias.asname or alias.name, node.lineno, "importfrom", node,
                           target=alias, module=node.module or "", level=node.level,
                           attribute=alias.name)

    def _stmt_Global(self, scope, node):
        pass

    _stmt_Nonlocal = _stmt_Global

    # -- expressions -------------------------------------------------------

    def _expression(self, scope, node):
        if node is None or not isinstance(node, ast.AST):
            return
        if isinstance(node, ast.Lambda):
            for default in node.args.defaults + node.args.kw_defaults:
                self._expression(scope, default)
            child = self._new_scope(LAMBDA, node, scope)
            self._bind_arguments(child, node)
            self._expression(child, node.body)
        elif isinstance(node, _COMPREHENSION_NODES):
            child = self._new_scope(COMPREHENSION, node, scope)
            for index, generator in enumerate(node.generators):
                self._expression(scope if index == 0 else child, generator.iter)
                self._bind_target(child, generator.target, "comprehension", None, generator)
                for condition in generator.ifs:
                    self._expression(child, condition)
            if isinstance(node, ast.DictComp):
                self._expression(child, node.key)
                self._expression(child, node.value)
            else:
                self._expression(child, node.elt)
        elif isinstance(node, ast.NamedExpr):
            self._expression(scope, node.value)
            target_scope = scope
            while target_scope.kind == COMPREHENSION:
                target_scope = target_scope.parent
            self._bind(target_scope, node.target.id, node.target.lineno, "assign", node, node.value,
                       target=node.target)
        else:
            for child in ast.iter_child_nodes(node):
                self._expression(scope, child)

"""Flow-sensitive name resolution within a single scope.

For one name in one scope, the analyzer walks the scope's statements in
execution order and tracks which bindings may be in effect, as a list of
facts.  Branches (`if`, loops, `try`, `match`) merge the facts of every path;
`return`, `raise`, `break` and `continue` end a path.  Conditions such as
`isinstance(x, A)` or `x is None` attach narrowings to the facts of the
branches they guard.  Values are only inferred later, from the facts.
"""
import ast

from .scopes import COMPREHENSION, FUNCTION, LAMBDA, walk_local

_COMPOUND = (ast.If, ast.For, ast.AsyncFor, ast.While, ast.With, ast.AsyncWith, ast.Try, ast.Match)
if hasattr(ast, "TryStar"):
    _COMPOUND += (ast.TryStar,)
# Nodes whose children are not evaluated as part of the enclosing statement's header.
_NOT_HEADER = (ast.stmt, ast.Lambda, ast.excepthandler, ast.match_case)


class Narrowing:
    """A condition known to hold (`positive`) or not for a name at some point.

    Kinds: "isinstance" (`node` is the class expression, evaluated in
    `scope`), "none" (`x is None`) and "truthy" (`if x:`).
    """

    def __init__(self, kind, positive, node=None, scope=None):
        self.kind = kind
        self.positive = positive
        self.node = node
        self.scope = scope

    @property
    def key(self):
        return (self.kind, self.positive, id(self.node))


class Fact:
    """One way a name may be bound at a program point.

    `binding` is None when the name refers to an enclosing scope (or is not
    yet bound here).  `prior` holds the facts an augmented assignment updates.
    """

    def __init__(self, binding, narrowings=(), prior=()):
        self.binding = binding
        self.narrowings = tuple(narrowings)
        self.prior = tuple(prior)

    @property
    def key(self):
        return (id(self.binding), tuple(n.key for n in self.narrowings),
                tuple(p.key for p in self.prior))

    def narrowed(self, narrowing):
        return Fact(self.binding, self.narrowings + (narrowing,), self.prior)


def merge(*states):
    """The union of several lists of facts, without duplicates."""
    seen = set()
    result = []
    for state in states:
        for fact in state:
            if fact.key not in seen:
                seen.add(fact.key)
                result.append(fact)
    return result


def start_of(node):
    return (node.lineno, node.col_offset)


def end_of(node):
    return (node.end_lineno, node.end_col_offset)


class _Found(Exception):
    def __init__(self, state):
        super().__init__()
        self.state = state


class _Loop:
    def __init__(self):
        self.breaks = []
        self.continues = []


class FlowAnalyzer:
    """Computes the facts for `name` in `scope` at `target` ((line, byte col) or None for the end).

    `synthetic(kind, node, name)` creates bindings that scope analysis does
    not record: "star" for `from m import *` and "aug" for `x += ...`.
    """

    def __init__(self, scope, name, target, synthetic):
        self.scope = scope
        self.name = name
        self.target = target
        self.synthetic = synthetic
        self.searching = target is not None
        self.by_node = {}
        self.seen = set()
        self.loops = []
        for binding in scope.bindings.get(name, []):
            self.by_node.setdefault(id(binding.node), []).append(binding)
        self.has_walrus = any(isinstance(b.node, ast.NamedExpr) for b in scope.bindings.get(name, []))

    def run(self, initial):
        bindings = self.scope.bindings.get(self.name, [])
        if self.scope.kind in (LAMBDA, COMPREHENSION):
            return [Fact(b) for b in bindings] or list(initial)
        body = self.scope.node.body
        # Bindings made elsewhere, by functions declaring the name `global`.
        local = self.scope.local_node_ids
        if local is None:
            local = self.scope.local_node_ids = {id(node) for node in walk_local(body)}
        foreign = [Fact(b) for b in bindings if b.kind != "param" and id(b.node) not in local]
        try:
            state = self.block(body, list(initial))
        except _Found as found:
            state = found.state
            if not state or all(fact.binding is None for fact in state):
                return state
        return merge(state, foreign)

    # -- statements ----------------------------------------------------------

    def block(self, statements, state):
        for statement in statements:
            if self.searching:
                if self.target < start_of(statement):
                    raise _Found(state)
                if self.target <= end_of(statement):
                    self._enter(statement, state)
            state = self.statement(statement, state)
        return state

    def _enter(self, statement, state):
        """The target lies within `statement`: find the facts that reach it."""
        first = _first_child_start(statement)
        if first is None or self.target < first:
            raise _Found(state)
        raise _Found(self.statement(statement, state))

    def statement(self, node, state):
        handler = getattr(self, "_" + type(node).__name__, None)
        if handler is not None:
            return handler(node, state)
        return self._bind(node, self.walrus(node, state))

    def _bind(self, node, state):
        """The state after `node` binds the name (unchanged if it does not)."""
        bindings = self.by_node.get(id(node))
        if not bindings:
            return state
        for binding in bindings:
            self.seen.add(id(binding))
        return [Fact(bindings[-1])]

    def walrus(self, node, state):
        """Apply `(name := value)` bindings found in the header expressions of `node`."""
        if not self.has_walrus:
            return state
        stack = [c for c in ast.iter_child_nodes(node) if not isinstance(c, _NOT_HEADER)]
        if isinstance(node, ast.expr):
            stack = [node]
        while stack:
            child = stack.pop()
            if isinstance(child, ast.NamedExpr):
                state = self._bind(child, state)
            stack.extend(c for c in ast.iter_child_nodes(child) if not isinstance(c, _NOT_HEADER))
        return state

    def _ImportFrom(self, node, state):
        if any(alias.name == "*" for alias in node.names):
            binding = self.synthetic("star", node, self.name)
            return [Fact(binding)] if binding is not None else state
        return self._bind(node, state)

    def _AugAssign(self, node, state):
        state = self.walrus(node.value, state)
        if isinstance(node.target, ast.Name) and node.target.id == self.name:
            bindings = self.by_node.get(id(node))
            binding = bindings[-1] if bindings else self.synthetic("aug", node, self.name)
            self.seen.add(id(binding))
            return [Fact(binding, prior=state)]
        return state

    def _Delete(self, node, state):
        for target in node.targets:
            if isinstance(target, ast.Name) and target.id == self.name:
                return []
        return state

    def _Return(self, node, state):
        self.walrus(node, state)
        return []

    _Raise = _Return

    def _Break(self, node, state):
        if self.loops:
            self.loops[-1].breaks.extend(state)
        return []

    def _Continue(self, node, state):
        if self.loops:
            self.loops[-1].continues.extend(state)
        return []

    def _Assert(self, node, state):
        return self.branch(node.test, self.walrus(node, state), True)

    def _If(self, node, state):
        state = self.walrus(node.test, state)
        body = self.block(node.body, self.branch(node.test, state, True))
        orelse = self.block(node.orelse, self.branch(node.test, state, False))
        return merge(body, orelse)

    def _loop(self, node, state, enter):
        """(state when the loop ends normally, states at `break`)."""
        searching = self.searching
        self.searching = False
        self.loops.append(_Loop())
        try:
            first = self.block(node.body, enter(state))
        finally:
            loop = self.loops.pop()
            self.searching = searching
        start = merge(state, first, loop.continues)
        self.loops.append(_Loop())
        try:
            end = self.block(node.body, enter(start))
        finally:
            loop = self.loops.pop()
        return merge(start, end, loop.continues), loop.breaks

    def _While(self, node, state):
        state = self.walrus(node.test, state)
        exit_state, breaks = self._loop(node, state, lambda s: self.branch(node.test, s, True))
        if isinstance(node.test, ast.Constant) and node.test.value:
            exit_state = []
        else:
            exit_state = self.branch(node.test, exit_state, False)
        return merge(self.block(node.orelse, exit_state), breaks)

    def _For(self, node, state):
        state = self.walrus(node.iter, state)
        bindings = self.by_node.get(id(node))
        if bindings:
            for binding in bindings:
                self.seen.add(id(binding))
            enter = lambda s: [Fact(bindings[-1])]
        else:
            enter = lambda s: s
        exit_state, breaks = self._loop(node, state, enter)
        return merge(self.block(node.orelse, exit_state), breaks)

    _AsyncFor = _For

    def _With(self, node, state):
        for item in node.items:
            state = self.walrus(item.context_expr, state)
        return self.block(node.body, self._bind(node, state))

    _AsyncWith = _With

    def _Try(self, node, state):
        body = self.block(node.body, state)
        handler_start = merge(state, body)
        ends = [self.block(node.orelse, body)]
        for handler in node.handlers:
            ends.append(self.block(handler.body, self._bind(handler, handler_start)))
        result = merge(*ends)
        if not node.finalbody:
            return result
        after = self.block(node.finalbody, merge(result, handler_start))
        return after if result else []

    _TryStar = _Try

    def _Match(self, node, state):
        state = self.walrus(node.subject, state)
        ends = [state]
        for case in node.cases:
            ends.append(self.block(case.body, self._bind(case, state)))
        return merge(*ends)

    # -- conditions ------------------------------------------------------------

    def branch(self, test, state, positive):
        """The facts in the branch where `test` is true (`positive`) or false."""
        if not state:
            return state
        if isinstance(test, ast.UnaryOp) and isinstance(test.op, ast.Not):
            return self.branch(test.operand, state, not positive)
        if isinstance(test, ast.BoolOp):
            if isinstance(test.op, ast.And) == positive:
                for value in test.values:
                    state = self.branch(value, state, positive)
                return state
            result = []
            for value in test.values:
                result = merge(result, self.branch(value, state, positive))
                state = self.branch(value, state, not positive)
            return result
        narrowing = self._narrowing(test, positive)
        if narrowing is None:
            return state
        return [fact.narrowed(narrowing) for fact in state]

    def _is_subject(self, node):
        if isinstance(node, ast.NamedExpr):
            node = node.target
        return isinstance(node, ast.Name) and node.id == self.name

    def _narrowing(self, test, positive):
        if self._is_subject(test):
            return Narrowing("truthy", True) if positive else None
        if isinstance(test, ast.Call) and isinstance(test.func, ast.Name) and len(test.args) == 2:
            if test.func.id == "isinstance" and self._is_subject(test.args[0]):
                return Narrowing("isinstance", positive, test.args[1], self.scope)
            return None
        if isinstance(test, ast.Compare) and len(test.ops) == 1:
            left, op, right = test.left, test.ops[0], test.comparators[0]
            if _is_none(left) and self._is_subject(right):
                left, right = right, left
            if self._is_subject(left) and _is_none(right):
                if isinstance(op, (ast.Is, ast.Eq)):
                    return Narrowing("none", positive)
                if isinstance(op, (ast.IsNot, ast.NotEq)):
                    return Narrowing("none", not positive)
            if (positive and isinstance(op, (ast.Is, ast.Eq)) and isinstance(left, ast.Call)
                    and isinstance(left.func, ast.Name) and left.func.id == "type"
                    and len(left.args) == 1 and self._is_subject(left.args[0])):
                return Narrowing("isinstance", True, right, self.scope)
        return None


def _is_none(node):
    return isinstance(node, ast.Constant) and node.value is None


def _first_child_start(statement):
    """Start of the first nested statement (or case) of a compound statement."""
    if not isinstance(statement, _COMPOUND):
        return None
    if isinstance(statement, ast.Match):
        return start_of(statement.cases[0].pattern) if statement.cases else None
    return start_of(statement.body[0]) if statement.body else None


def initial_facts(scope, name):
    """Facts at the start of `scope`: its parameter binding, or the enclosing scope."""
    if scope.kind == FUNCTION:
        params = [b for b in scope.bindings.get(name, []) if b.kind == "param"]
        if params:
            return [Fact(params[-1])]
    return [Fact(None)]

